def scenario_exactly_one(label, guard, bind_args, check_args_fn, verify_name,
                         rounds=30, n=16):
    """N barrier-started concurrent checks; exactly one True, and it consumes."""
    original = getattr(zkregion, verify_name)

    def slow(*a, **kw):
        time.sleep(0.02)  # keep the claim held while losers race
        return original(*a, **kw)

    with patch(verify_name, slow):
        for r in range(rounds):
            sid = f"s-{r}".encode()
            binding = guard.bind_once(*bind_args(), sid)
            barrier = threading.Barrier(n)
            args = check_args_fn(binding)

            def target(i):
                barrier.wait()
                return guard.check(*args, now=1)

            results, errors = run_threads(target, n)
            for e in errors:
                if e is not None:
                    failures.append(f"{label} round {r} thread error")
                    print(e)
            trues = sum(1 for v in results if v is True)
            check(f"{label}: exactly one True (round {r})", trues == 1)

